from pathlib import Path

path = Path('backend/src/adk/tools.py')
text = path.read_text(encoding='utf-8')

anchor = '''async def _duckduckgo_search(query: str, max_items: int = 8) -> List[Dict[str, str]]:\n'''
if anchor not in text:
    raise SystemExit('duckduckgo anchor missing')

bing = '''async def _bing_html_search(query: str, max_items: int = 8) -> List[Dict[str, str]]:\n    \"\"\"Independent Bing HTML fallback for hosts where DDG/Jina are blocked.\"\"\"\n    import urllib.parse\n\n    client = _get_firecrawl_client()\n    headers = {\n        \"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/125.0 Safari/537.36\",\n        \"Accept\": \"text/html,application/xhtml+xml\",\n        \"Accept-Language\": \"en-US,en;q=0.9\",\n    }\n    results: List[Dict[str, str]] = []\n    try:\n        resp = await client.get(\n            \"https://www.bing.com/search\",\n            params={\"q\": query, \"count\": max_items},\n            headers=headers,\n            follow_redirects=True,\n            timeout=8.0,\n        )\n        if resp.status_code == 200 and resp.text:\n            from bs4 import BeautifulSoup\n            soup = BeautifulSoup(resp.text, \"html.parser\")\n            for item in soup.select(\"li.b_algo\")[:max_items]:\n                link = item.select_one(\"h2 a\")\n                if not link:\n                    continue\n                title = link.get_text(\" \", strip=True)\n                url = (link.get(\"href\") or \"\").strip()\n                snippet_node = item.select_one(\".b_caption p\") or item.select_one(\"p\")\n                snippet = snippet_node.get_text(\" \", strip=True) if snippet_node else \"\"\n                if title and url and snippet and _validate_outbound_url(url):\n                    results.append({\"title\": title, \"url\": url, \"snippet\": snippet, \"source\": \"Bing Web\"})\n    except Exception as exc:\n        logger.warning(f\"Bing HTML search failed for '{query}': {exc}\")\n    return results\n\n\n'''
text = text.replace(anchor, bing + anchor, 1)

old_tasks = '''    tasks = [\n        _duckduckgo_search(clean_query, max_items=min(result_limit, 8)),\n        _jina_search_items(clean_query, max_items=min(result_limit, 6)),\n    ]\n'''
new_tasks = '''    tasks = [\n        _duckduckgo_search(clean_query, max_items=min(result_limit, 8)),\n        _jina_search_items(clean_query, max_items=min(result_limit, 6)),\n        _bing_html_search(clean_query, max_items=min(result_limit, 8)),\n    ]\n'''
if old_tasks not in text:
    raise SystemExit('task list anchor missing')
text = text.replace(old_tasks, new_tasks, 1)

old_fallback = '''    # 4. Academic/Encyclopedic fallbacks if live web results are sparse\n    if len(raw_items) < 3:\n        try:\n            wiki_res = await _wikipedia_search(clean_query)\n            if wiki_res and len(wiki_res.strip()) > 30:\n                raw_items.append({\"title\": \"Wikipedia Reference\", \"url\": \"\", \"snippet\": wiki_res, \"source\": \"Wikipedia\"})\n        except Exception:\n            pass\n\n    # Deduplicate results by URL and title\n'''
new_fallback = '''    # 4. Academic/Encyclopedic fallback. Primary engines can return malformed\n    # placeholders, so count usable items rather than raw responses.\n    usable_before_fallback = [\n        item for item in raw_items\n        if str(item.get(\"title\", \"\")).strip() and str(item.get(\"snippet\", \"\")).strip()\n    ]\n    if len(usable_before_fallback) < 3:\n        try:\n            wiki_res = await _wikipedia_search(clean_query)\n            if wiki_res and len(wiki_res.strip()) > 30:\n                raw_items.append({\"title\": \"Wikipedia Reference\", \"url\": \"\", \"snippet\": wiki_res, \"source\": \"Wikipedia\"})\n        except Exception:\n            pass\n\n    # Deduplicate results by URL and title\n'''
if old_fallback not in text:
    raise SystemExit('fallback anchor missing')
text = text.replace(old_fallback, new_fallback, 1)
path.write_text(text, encoding='utf-8')

qpath = Path('backend/src/api/routes/_chat_quality.py')
qtext = qpath.read_text(encoding='utf-8')
old = '''    search_results = "\\n\\n---\\n\\n".join(evidence_parts)\n    citations = _citations_from_search_text(search_results)\n    if not citations:\n        return None\n'''
new = '''    search_results = "\\n\\n---\\n\\n".join(evidence_parts)\n    citations = _citations_from_search_text(search_results)\n    if not citations:\n        # Be tolerant to search-provider formatting changes. Only URLs returned\n        # by the actual search tool count as evidence; model text is never used\n        # to manufacture citations.\n        seen_urls: set[str] = set()\n        fallback_citations: list[dict[str, str]] = []\n        current_title = "Web source"\n        for raw_line in search_results.splitlines():\n            line = raw_line.strip()\n            heading = re.match(r"^###(?:\\s+Source\\s+\\d+:|\\s+\\[[^]]+\\])?\\s*(.+)$", line, re.I)\n            if heading:\n                current_title = heading.group(1).strip() or "Web source"\n            for url in re.findall(r"https?://[^\\s)<>\\]\\\"']+", line, re.I):\n                clean_url = url.rstrip(".,;:")\n                if clean_url and clean_url not in seen_urls:\n                    seen_urls.add(clean_url)\n                    fallback_citations.append({\n                        "file_name": current_title,\n                        "text": clean_url,\n                        "url": clean_url,\n                    })\n        citations = fallback_citations\n    if not citations:\n        return None\n'''
if old not in qtext:
    raise SystemExit('grounded rescue citation anchor missing')
qtext = qtext.replace(old, new, 1)
qpath.write_text(qtext, encoding='utf-8')

# Regression tests
test = Path('backend/tests/test_grounding_search_reliability.py')
test.write_text('''import pytest\n\nfrom src.adk import tools\nfrom src.api.routes import _chat_quality as quality\n\n\n@pytest.mark.asyncio\nasync def test_web_search_uses_bing_when_other_engines_are_empty(monkeypatch):\n    async def empty(*args, **kwargs):\n        return []\n\n    async def bing(*args, **kwargs):\n        return [{\n            "title": "Official Example",\n            "url": "https://example.org/location",\n            "snippet": "Example is located in Goa.",\n            "source": "Bing Web",\n        }]\n\n    async def no_wiki(*args, **kwargs):\n        return None\n\n    tools._web_search_cache.clear()\n    monkeypatch.setattr(tools, "_duckduckgo_search", empty)\n    monkeypatch.setattr(tools, "_jina_search_items", empty)\n    monkeypatch.setattr(tools, "_bing_html_search", bing)\n    monkeypatch.setattr(tools, "_searxng_search_items", empty)\n    monkeypatch.setattr(tools, "_wikipedia_search", no_wiki)\n\n    result = await tools.web_search("Example Goa", for_research=True, max_items=8)\n    assert "https://example.org/location" in result\n    assert "Official Example" in result\n\n\n@pytest.mark.asyncio\nasync def test_grounded_rescue_accepts_tool_url_when_primary_parser_misses(monkeypatch):\n    async def fake_search(*args, **kwargs):\n        return "### [Official] PCCE\\nhttps://pccegoa.edu.in/contact-us/\\nVerna Goa 403722"\n\n    async def fake_generate(**kwargs):\n        return "PCCE is in Verna, Goa."\n\n    from src.adk import runner\n    from src.services.llm import llm_service\n    monkeypatch.setattr(tools, "web_search", fake_search)\n    monkeypatch.setattr(runner, "_citations_from_search_text", lambda text: [])\n    monkeypatch.setattr(llm_service, "generate", fake_generate)\n\n    result = await quality._grounded_rescue("Where is PCCE Goa?")\n    assert result is not None\n    assert result["citations"]\n    assert result["citations"][0]["url"] == "https://pccegoa.edu.in/contact-us/"\n''', encoding='utf-8')
